    rows=[core(t) for t in r.get("chats",[])]
    if len(rows)!=len(new2) or checksum(rows[:-1])!=checksum(before):
        raise Blocked("registration_readback_conflict")
    last=rows[-1]
    if last.get("id")!=CURATOR_ID or last.get("profileId")!=profile["id"]:
        raise Blocked("registration_readback_identity_mismatch")
    print("REGISTERED_EXACT. Other managed records preserved; watchdog unchanged.")
    print("Backup stored locally, no secrets included.")

if __name__=="__main__":
    try:main()
